INSERT INTO mx_device.rule_definitions VALUES ('sim:pacing.default:1','sim','pacing.default',1,'{"id":"sim:pacing.default:1","mode":"sim","code":"pacing.default","name":"节奏账本 · 默认","description":"同 App 60 秒内 3 个小任务或 1 个大任务后随机休息 4–8 秒；整机连续服务与账号预算关闭。与旧的机架循环默认值一致。","kind":"pacing","config":{"burstWindowMs":60000,"smallLimit":3,"largeLimit":1,"burstRestMinMs":4000,"burstRestMaxMs":8000,"continuousCapMs":0,"continuousRestMs":0,"accountMinGapMs":0,"accountWindowMs":60000,"accountMaxRuns":0,"accountMaxServiceMs":0,"accountRestMs":0,"accountDailyCap":0},"version":1,"archived":false,"createdAt":0}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO mx_device.strategy_definitions VALUES ('sim:pool.paced:1','sim','pool.paced',1,'{"id":"sim:pool.paced:1","mode":"sim","code":"pool.paced","name":"均衡 + 节奏账本","description":"均衡自适应加统一节奏规则：随机休息由策略管理，可在节奏规则里开启整机连续服务上限和账号预算。","version":1,"archived":false,"recommended":false,"rules":[{"code":"placement.adaptive","version":1,"definition":{"id":"sim:placement.adaptive:1","mode":"sim","code":"placement.adaptive","name":"均衡分配 · 自适应","description":"空闲设备超过 50% 时倾向分散；否则优先复用同 App，额外等待不超过 3 秒。","kind":"placement","config":{"strategy":"adaptive","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000},"version":1,"archived":false,"createdAt":0}},{"code":"queue.bounded","version":1,"definition":{"id":"sim:queue.bounded:1","mode":"sim","code":"queue.bounded","name":"有界候选队列","description":"预计排队超过 30 秒时保留在中心等待；每机最多 100 个候选任务，15 秒短任务阈值。","kind":"queue","config":{"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000},"version":1,"archived":false,"createdAt":0}},{"code":"budget.default","version":1,"definition":{"id":"sim:budget.default:1","mode":"sim","code":"budget.default","name":"App 默认运行预算","description":"60 秒窗口，最多 3 个任务或 60 秒服务时间，达到预算后休息 5 秒。","kind":"app-budget","config":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"version":1,"archived":false,"createdAt":0}},{"code":"pacing.default","version":1,"definition":{"id":"sim:pacing.default:1","mode":"sim","code":"pacing.default","name":"节奏账本 · 默认","description":"同 App 60 秒内 3 个小任务或 1 个大任务后随机休息 4–8 秒；整机连续服务与账号预算关闭。与旧的机架循环默认值一致。","kind":"pacing","config":{"burstWindowMs":60000,"smallLimit":3,"largeLimit":1,"burstRestMinMs":4000,"burstRestMaxMs":8000,"continuousCapMs":0,"continuousRestMs":0,"accountMinGapMs":0,"accountWindowMs":60000,"accountMaxRuns":0,"accountMaxServiceMs":0,"accountRestMs":0,"accountDailyCap":0},"version":1,"archived":false,"createdAt":0}}],"policy":{"version":1,"enabled":true,"strategy":"adaptive","idleSpreadThresholdPct":50,"maxAffinityDelayMs":3000,"maxQueueWaitMs":30000,"maxQueuePerDevice":100,"shortTaskMs":15000,"switchCostMs":3000,"stickyGainMs":2000,"stickyGainPct":20,"maxPlanMoves":3,"planFreezeMs":1000,"pacing":{"burst":{"windowMs":60000,"smallLimit":3,"largeLimit":1,"restMinMs":4000,"restMaxMs":8000},"continuous":null,"account":null},"appDefaults":{"windowMs":60000,"maxRuns":3,"maxServiceMs":60000,"cooldownMs":5000},"appPolicies":{}},"createdAt":0}'::jsonb) ON CONFLICT DO NOTHING;
